function xBtn(id){ const c=XC[id]; if(!c)return null; const b=document.createElement('button'); b.className='xb'+(c.on&&c.on()?' on':''); b.title=c.t[L2()]; b.dataset.cmd=id; b.innerHTML=ico(c.ic,34)+'<span>'+c.t[L2()]+'</span>'; b.onclick=()=>{try{c.run();}catch(e){say('st_err',e.message||String(e));} xSync();}; return b; }
function xRibbon(){ const tabs=$('xTabs'), rib=$('xRib'); if(!tabs)return; tabs.innerHTML=''; RIB.forEach(t=>{const b=el('button',{class:t[0]===XTAB?'on':'',text:t[1][L2()],onclick:()=>{XTAB=t[0]; xRibbon();}}); tabs.appendChild(b);}); rib.innerHTML=''; const cur=RIB.find(t=>t[0]===XTAB); cur[2].forEach(g=>{const d=el('div',{class:'xg'}), bs=el('div',{class:'bs'}); g[1].forEach(id=>{const b=xBtn(id); if(b)bs.appendChild(b);}); d.append(bs,el('div',{class:'gt',text:g[0][L2()]})); rib.appendChild(d);}); }
function xSync(){ document.querySelectorAll('#xRib .xb').forEach(b=>{const c=XC[b.dataset.cmd]; b.classList.toggle('on',!!(c&&c.on&&c.on()));}); const u=$('xUndo'), r=$('xRedo'); if(u){u.disabled=HI.i<=0; r.disabled=HI.i>=HI.st.length-1;} xBar(true); }
